505	func (engine *Engine) validateHeader(header string) (clientIP string, valid bool) {
506		if header == "" {
507			return "", false
508		}
509		items := strings.Split(header, ",")
510		for i := len(items) - 1; i >= 0; i-- {
511			ipStr := strings.TrimSpace(items[i])
